import kotlin.math.*

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val n = reader.readLine().trim().toLong()

    var low = 0L
    var high = 60L  // enough since 2^60 > 1e18

    fun maxPlayers(k: Long): Long {
        // maximum players that allow winner to play k games
        // sum_{i=0}^{k} floor(i/2) = floor(k^2 / 4)
        return (k * k) / 4
    }

    while (low < high) {
        val mid = (low + high + 1) / 2
        if (maxPlayers(mid) <= n) {
            low = mid
        } else {
            high = mid - 1
        }
    }

    println(low)
}

