fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val n = reader.readLine().trim().toLong()

    var low = 0L
    var high = 60L  // enough since 2^60 > 1e18

    while (low < high) {
        val mid = (low + high + 1) / 2
        // compute 2^mid safely with early stop
        var pow = 1L
        var ok = true
        for (i in 1..mid) {
            if (pow > n / 2) { // 2^mid > n
                ok = false
                break
            }
            pow = pow shl 1
        }
        if (ok && pow <= n) {
            low = mid
        } else {
            high = mid - 1
        }
    }

    println(low)
}

