import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.*

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val n = reader.readLine().trim().toLong()

    var low = 0L
    var high = 60L  // since n <= 1e18, log2(n) < 60

    fun can(k: Long): Boolean {
        // Check if 2^k <= n <= 2^(k+1) - 1
        val powK = 1L shl k.toInt()
        val powK1 = 1L shl (k + 1).toInt()
        return n >= powK && n <= powK1 - 1
    }

    while (low < high) {
        val mid = (low + high + 1) / 2
        if (can(mid)) low = mid else high = mid - 1
    }

    println(low)
}

